        if (cars == null || cars.isEmpty()) {
            return null; // Return null if the list is empty
        }

        Map<String, Integer> colorCount = new HashMap<>();
        String mostPopularColor = "";
        int maxCount = 0;

        for (Car car : cars) {
            String color = car.getColor();
            int count = colorCount.getOrDefault(color, 0) + 1;
            colorCount.put(color, count);

            if (count > maxCount) {
                maxCount = count;
                mostPopularColor = color;
            }
        }

        return new HashMap.SimpleEntry<>(mostPopularColor, maxCount);
    }

    public static void main(String[] args) {
        List<Car> cars = List.of(
            new Car("Red"),
            new Car("Blue"),
            new Car("Red"),
            new Car("Green"),
            new Car("Red"),
            new Car("Blue")
        );

        Map.Entry<String, Integer> result = findMostPopularCarColor(cars);
        if (result != null) {
            System.out.println("Most popular color: " + result.getKey() + ", Count: " + result.getValue());
        } else {
            System.out.println("No cars in the list.");
        }
    }
}
```

